function skeletonCss(opts){
  opts=opts||{};
  var h=opts.height!=null?opts.height:16;
  var radius=opts.radius!=null?opts.radius:6;
  var gap=opts.gap!=null?opts.gap:10;
  var color=opts.color||'#e5e7eb';
  var hl=opts.highlight||'#f3f4f6';
  var L=[];
  L.push('.skeleton {');
  L.push('  height: '+h+'px;');
  L.push('  border-radius: '+radius+'px;');
  L.push('  margin-bottom: '+gap+'px;');
  L.push('  background: '+color+';');
  L.push('  background-image: linear-gradient(90deg, '+color+' 0%, '+hl+' 50%, '+color+' 100%);');
  L.push('  background-size: 200% 100%;');
  L.push('  animation: skeleton-shimmer 1.4s ease-in-out infinite;');
  L.push('}');
  L.push('@keyframes skeleton-shimmer {');
  L.push('  0% { background-position: 200% 0; }');
  L.push('  100% { background-position: -200% 0; }');
  L.push('}');
  return L.join('\n');
}

var EXPORTS={skeletonCss:skeletonCss};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SkeletonForgePure = EXPORTS; }
